+ * options.minAmount keeps only records whose absolute amount is at least that threshold; the total covers those records.
+ */
+export function renderExport(ledger, { format = "csv", minAmount } = {}) {
+  const min = minAmount === undefined ? undefined : parseMinAmount(minAmount, ledger.locale);
+  const records = min === undefined ? ledger.records : ledger.records.filter((r) => Math.abs(r.amount) >= min);
