+/**
+ * Parse minAmount in the ledger's own notation (locale, currency prefix) into cents.
+ * Negative or unparseable values throw RangeError.
+ */
+function parseMinAmount(minAmount, locale) {
+  let cents;
+  try {
+    cents = parseAmount(minAmount, { locale });
+  } catch {
+    throw new RangeError(`invalid minAmount: ${JSON.stringify(minAmount)}`);
+  }
+  if (cents < 0) throw new RangeError(`minAmount must not be negative: ${JSON.stringify(minAmount)}`);
+  return cents;
+}
+
+/**
+ * Render a ledger as "csv" (rows plus a TOTAL row) or "json" ({ locale, records, total } in cents).
+ * options.minAmount (optional): keep only records whose absolute amount is >= the threshold; the total covers those records only.
+ */
+export function renderExport(ledger, { format = "csv", minAmount } = {}) {
+  let records = ledger.records;
+  if (minAmount !== undefined) {
+    const threshold = parseMinAmount(minAmount, ledger.locale);
+    records = records.filter((record) => Math.abs(record.amount) >= threshold);
+  }
+  const total = records.reduce((sum, record) => sum + record.amount, 0);
+  if (format === "json") return JSON.stringify({ locale: ledger.locale, records, total }, null, 2) + "\n";
