+test("min-amount CSV TOTAL covers only exported rows", () => {
+  const out = exportFile("data/q3-en.csv", { minAmount: "999.99" });
+  assert.equal(out.trim().split("\n").length, 6); // header + 4 rows + TOTAL
+  assert.match(out, /,,TOTAL,"13,499.99"\n$/);
+});
+
+test("min-amount uses the file's locale and currency prefix", () => {
+  const one = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "€ 8.400,00" }));
+  assert.deepEqual(one.records.map((r) => r.amount), [840000]);
+  const two = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "1.234,50" }));
+  assert.deepEqual(two.records.map((r) => r.amount), [840000, -123450]);
+  assert.equal(two.total, 716550);
+});
+
+test("min-amount rejects negative and unparseable thresholds with RangeError", () => {
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "-5" }), RangeError);
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "abc" }), RangeError);
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "" }), RangeError);
+  assert.throws(() => exportFile("data/q3-de.csv", { minAmount: "1,000.00" }), RangeError);
+});
+
+test("CLI min-amount works before or after the file and reports bad values as input errors", () => {
+  const before = execFileSync("node", ["bin/ledger.js", "export", "--min-amount", "1000", "data/q3-en.csv"], { encoding: "utf8" });
+  const after = execFileSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount", "1000"], { encoding: "utf8" });
+  assert.equal(before, after);
+  assert.equal(before.trim().split("\n").length, 5); // header + 3 rows + TOTAL
+
+  const run = (args) => {
+    try {
+      execFileSync("node", ["bin/ledger.js", "export", ...args], { encoding: "utf8", stdio: "pipe" });
+    } catch (error) {
+      return error;
+    }
+    throw new Error("expected failure");
+  };
+  const negative = run(["data/q3-en.csv", "--min-amount", "-5"]);
+  assert.equal(negative.status, 2);
+  assert.match(negative.stderr, /^error: minAmount must not be negative/m);
+  const missing = run(["data/q3-en.csv", "--min-amount"]);
+  assert.equal(missing.status, 2);
+  assert.match(missing.stderr, /error: --min-amount needs a value/);
+});

