+    ...records.map((r) => [r.date, r.account, r.description, amount(r.amount)]),
     ["", "", "TOTAL", amount(total)],
   ]);
 }
+
+function filterByMinAmount(ledger, minAmount) {
+  let threshold;
+  try {
+    threshold = parseAmount(minAmount, { locale: ledger.locale });
+  } catch (error) {
+    throw new RangeError(`invalid minAmount: ${error.message}`);
+  }
+  if (threshold < 0) throw new RangeError(`minAmount must not be negative: ${minAmount}`);
+  return ledger.records.filter((record) => Math.abs(record.amount) >= threshold);
