const refund07 = await import(`${root}/src/services/refund07.js`);
const inputs = [
  { id: 1, items: [1, 2, 3], ok: true, failed: false },
  { id: 2, items: [1], ok: false, failed: true },
  { id: 3, items: [], ok: true, failed: true },
  { id: 4, items: [5, 6, 7, 8], ok: false, failed: false },
];
const result = [];
for (const input of inputs) {
  for (const [name, run] of Object.entries(modules)) {
    const events = [];
    const remove = addSink((e) => events.push(e));
    let ret, err = null;
    try { ret = run(structuredClone(input)); } catch (e) { err = String(e); }
    remove();
    result.push({ input: input.id, name, ret, err, events });
