  for (const [name, mod] of [["cache19.forward", cache19], ["refund07.forward", refund07]]) {
    const calls = [];
    const ret = mod.forward((level, message) => calls.push([level, message]), input.items);
    result.push({ input: input.id, name, ret, calls });
  }
}
console.log(JSON.stringify(result, null, 1));
