   assert.equal(JSON.parse(out).records.length, 6);
 });
+
+test("min amount keeps |amount| >= threshold (inclusive) and totals only kept rows", () => {
+  // en amounts in cents: 1250000, -8420, 100000, 99999, -100000, -750
+  const out = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "1000.00" }));
+  assert.deepEqual(out.records.map((r) => r.amount), [1250000, 100000, -100000]);
+  assert.equal(out.total, 1250000);
+
+  const csv = exportFile("data/q3-en.csv", { minAmount: "1,000" });
+  assert.match(csv, /,,TOTAL,"12,500.00"\n$/);
+  assert.equal(csv.trimEnd().split("\n").length, 1 + 3 + 1);
+});
+
+test("min amount uses the file's locale and currency prefix", () => {
+  // de amounts in cents: 840000, -123450, 123449, -1200, 98000
+  const out = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "€ 1.234,50" }));
+  assert.deepEqual(out.records.map((r) => r.amount), [840000, -123450]);
+  assert.equal(out.total, 716550);
+
+  const inclusive = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "1.234,49" }));
+  assert.equal(inclusive.records.length, 3);
+});
+
+test("min amount matching nothing gives an empty export", () => {
+  const out = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "1000000" }));
+  assert.deepEqual(out.records, []);
+  assert.equal(out.total, 0);
+});
+
+test("invalid min amount throws RangeError", () => {
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "-5.00" }), RangeError);
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "(5.00)" }), RangeError);
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "abc" }), RangeError);
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "" }), RangeError);
+  assert.throws(() => exportFile("data/q3-de.csv", { minAmount: "1,234.50" }), RangeError);
+});
+
+test("CLI --min-amount works before and after the file", () => {
+  const before = JSON.parse(execFileSync("node", ["bin/ledger.js", "export", "--min-amount", "1000", "data/q3-en.csv", "--format", "json"], { encoding: "utf8" }));
+  const after = JSON.parse(execFileSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--format", "json", "--min-amount", "1000"], { encoding: "utf8" }));
+  assert.equal(before.records.length, 3);
+  assert.deepEqual(after, before);
+});
+
+test("CLI reports invalid --min-amount like other input errors", () => {
+  for (const value of ["-5", "abc"]) {
+    const result = spawnSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount", value], { encoding: "utf8" });
+    assert.equal(result.status, 2);
+    assert.equal(result.stdout, "");
+    assert.match(result.stderr, /^error: /);
+    assert.match(result.stderr, /usage: ledger export/);
+  }
+  const missing = spawnSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount"], { encoding: "utf8" });
+  assert.equal(missing.status, 2);
+  assert.match(missing.stderr, /--min-amount needs a value/);
+});

