import math, measure_analysis as m
def pdf(x,d1,d2):
    return math.exp(0.5*(d1*math.log(d1*x)+d2*math.log(d2)-(d1+d2)*math.log(d1*x+d2)) - math.log(x) - (math.lgamma(d1/2)+math.lgamma(d2/2)-math.lgamma((d1+d2)/2)) ) 
def sf_num(f,d1,d2,N=200000):
    # P(F>f) = 1 - int_0^f pdf ; Simpson
    h=f/N; s=pdf(1e-12,d1,d2)+pdf(f,d1,d2)
    for i in range(1,N):
        x=i*h; s+= (4 if i%2 else 2)*pdf(x,d1,d2)
    return 1-s*h/3
for f in [1.5,1.9,2.2]:
    print(f, 'closed-form', round(m.f_sf(f,18,60),6), 'numeric', round(sf_num(f,18,60),6))
# critical value by bisection
lo,hi=1,4
for _ in range(60):
    mid=(lo+hi)/2
    if m.f_sf(mid,18,60)>0.05: lo=mid
    else: hi=mid
print('crit F(18,60) at 0.05 =', round(lo,4))
"

