+  assert.deepEqual(out.records.map((r) => r.amount), [1250000, 100000, 99999, -100000]);
+  assert.equal(out.total, 1349999);
+});
+
+test("min amount total covers only kept records (csv)", () => {
+  const out = exportFile("data/q3-en.csv", { minAmount: "1000" });
+  assert.equal(out.split("\n").length - 1, 5);
+  assert.match(out, /,,TOTAL,"12,500.00"\n$/);
+});
+
+test("min amount uses the file's locale and currency prefix", () => {
+  const de = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "1.234,49" }));
+  assert.equal(de.records.length, 3);
+  assert.equal(de.total, 839999);
+  const en = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "$1,000.00" }));
+  assert.equal(en.records.length, 3);
+});
+
+test("invalid min amount is a RangeError", () => {
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "-1" }), RangeError);
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "abc" }), RangeError);
+  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "1.000,00" }), RangeError);
