+/**
+ * Render a ledger as "csv" (rows plus a TOTAL row) or "json" ({ locale, records, total } in cents).
+ * options.minAmount (optional): keep only records whose absolute amount is at least this value, written in the
+ * ledger's own notation (locale and currency prefix). Totals cover the exported records only.
+ */
+export function renderExport(ledger, { format = "csv", minAmount } = {}) {
+  const records = minAmount === undefined ? ledger.records : filterByMinAmount(ledger, minAmount);
+  const total = records.reduce((sum, record) => sum + record.amount, 0);
+  if (format === "json") return JSON.stringify({ locale: ledger.locale, records, total }, null, 2) + "\n";
   if (format !== "csv") throw new RangeError(`unknown format: ${format}`);
   const amount = (cents) => formatAmount(cents, { locale: ledger.locale });
   return writeCsv([
     ["date", "account", "description", "amount"],
-    ...ledger.records.map((r) => [r.date, r.account, r.description, amount(r.amount)]),
+    ...records.map((r) => [r.date, r.account, r.description, amount(r.amount)]),
     ["", "", "TOTAL", amount(total)],
   ]);
 }
+
+function filterByMinAmount(ledger, minAmount) {
+  let minimum;
+  try {
+    minimum = parseAmount(minAmount, { locale: ledger.locale });
+  } catch {
+    throw new RangeError(`invalid minimum amount: ${JSON.stringify(minAmount)}`);
+  }
+  // Object.is catches a negative sign on zero ("-0.00"), which parseAmount returns as -0.
+  if (minimum < 0 || Object.is(minimum, -0)) throw new RangeError(`minimum amount must not be negative: ${minAmount}`);
+  return ledger.records.filter((record) => Math.abs(record.amount) >= minimum);
+}
