set -e; PROJ=<scratch>/runs/1169fa6e2dd64514/work/project; rm -rf /tmp/equiv-check && mkdir -p /tmp/equiv-check/orig && cd $PROJ && git archive HEAD | tar -x -C /tmp/equiv-check/orig && cp -r $PROJ/src /tmp/equiv-check/new && cp $PROJ/package.json /tmp/equiv-check/new/ && cat > /tmp/equiv-check/compare.mjs <<'EOF'
import { isDeepStrictEqual } from "node:util";
const load = async (dir) => ({
  mods: await import(`${dir}/src/index.js`),
  log: await import(`${dir}/src/log.js`),
});
const A = await load("/tmp/equiv-check/orig");
const B = await load("/tmp/equiv-check/new");
const inputs = [];
for (const ok of [true, false]) for (const failed of [true, false]) for (const items of [[], [1], [1, 2, 3, 4]])
  inputs.push({ id: 7, ok, failed, items });
const capture = (L, run, input) => {
  const events = [];
  const remove = L.log.addSink((e) => events.push(e));
  let ret, err = null;
  try { ret = run(structuredClone(input)); } catch (e) { err = `${e.constructor.name}: ${e.message}`; }
  remove();
  return { events, ret, err };
};
let cases = 0, mismatches = 0, totalEvents = 0;
for (const [name, runA] of Object.entries(A.mods)) {
  const runB = B.mods[name];
  if (!runB) { mismatches++; console.log("missing export", name); continue; }
  for (const input of inputs) {
    cases++;
    const a = capture(A, runA, input), b = capture(B, runB, input);
    totalEvents += a.events.length;
    if (!isDeepStrictEqual(a, b)) { mismatches++; console.log("MISMATCH", name, JSON.stringify(input), JSON.stringify(a), JSON.stringify(b)); }
  }
}
