@@ -1,10 +1,19 @@
 import { readLedger } from "./read.js";
 import { renderExport } from "./export.js";
+import { parseAmount } from "./amount.js";

 /**
  * Programmatic entry point used by the reporting service.
  * options.format: "csv" (default) or "json".
+ * options.minAmount: keep only records with |amount| >= minAmount, written in the file's own locale and
+ * currency notation (e.g. "1,000.00" or "€ 1.000,00"). Negative or unparseable values throw RangeError.
  */
-export function exportFile(path, options = {}) {
-  return renderExport(readLedger(path), options);
+export function exportFile(path, { minAmount, ...options } = {}) {
+  const ledger = readLedger(path);
+  if (minAmount !== undefined) {
+    const min = parseAmount(minAmount, { locale: ledger.locale });
+    if (min < 0) throw new RangeError(`minAmount must not be negative: ${JSON.stringify(minAmount)}`);
+    ledger.records = ledger.records.filter((record) => Math.abs(record.amount) >= min);
+  }
+  return renderExport(ledger, options);
 }
